SELECT id,name,type,plan_start_time,plan_end_time,priority,status,
charge_name FROM project_task WHERE product_id=#{productId} AND charge_id=#{userId}

    AND phase_id=#{phaseId}





                AND name LIKE concat('%',#{item.searchKeyword},'%')




                AND priority =#{item.priority}




                AND person_in_charge_id =#{item.personInChargeId}




                AND status =#{item.status}




                AND create_time >=#{item.startTime}


                AND create_time >=#{item.endTime}

SELECT name AS taskName,charge_name AS taskChargeName,type AS taskType, status AS taskStatus FROM project_task
id IN
#{taskId}
